import fs from 'node:fs';
import path from 'node:path';
const root=process.cwd();
const out=path.join(root,'dist','chapters'); fs.mkdirSync(out,{recursive:true});
const read=p=>JSON.parse(fs.readFileSync(path.join(root,p),'utf8').replace(/^\uFEFF/,''));
const write=(p,v)=>fs.writeFileSync(path.join(root,p),JSON.stringify(v,null,2)+'\n','utf8');
const cast={Noor:{role:'Systeemanalist bij de nooddispatch',cell:0},Omar:{role:'Logistiek coördinator van het depot',cell:1},Mila:{role:'Reparatietechnicus en onderzoeker van ketenrecords',cell:2},Iris:{role:'Ontwerper van automatisering en reparatieplanning',cell:3},Eva:{role:'Investeerder en adviseur over zeggenschap',cell:4},Lena:{role:'Analist van marketing, aandacht en impact',cell:5}};
const opt=(id,text,correct,feedback)=>({id,text,correct,feedback});
const base=(type,title,intro,hint,explainAfter,concepts,sourceBlocks,boundary)=>({type,title,sceneObject:type==='inspect'||type==='connect'||type==='sort'?'evidence':type==='decision'?'person':'system',intro,hint,explainAfter,concepts,sourceBlocks,boundary});
const inspect=(b,rows)=>({...b,reveal:rows.map((r,i)=>({id:`r${i+1}`,label:r[0],title:r[1],text:r[2]})),required:rows.map((r,i)=>`r${i+1}`)});
const connect=(b,rows)=>({...b,pairs:rows.map((r,i)=>({id:`p${i+1}`,left:r[0],right:r[1],feedback:r[2]}))});
const sort=(b,categories,rows)=>({...b,categories:categories.map(c=>({id:c[0],label:c[1]})),cards:rows.map((r,i)=>({id:`c${i+1}`,text:r[0],category:r[1],feedback:r[2]}))});
const order=(b,rows)=>({...b,order:rows.map((r,i)=>({id:`s${i+1}`,text:r[0],feedback:r[1]})),correctOrder:rows.map((r,i)=>`s${i+1}`)});
const build=(b,options)=>({...b,options,required:options.filter(o=>o.correct).map(o=>o.id)});
const decision=(b,options)=>({...b,options});
const experiment=(b,spec)=>({...b,simulation:spec.id,simulationSpec:spec,minimumTrials:spec.minimumTrials});
const slot=(id,label,evidenceBeatId,options)=>({id,label,evidenceBeatId,options});
const area=(lesson,n,name,imageKey,exit,people,beats,slots,conclusion)=>({id:`${lesson}-${String(n).padStart(2,'0')}`,world:{name,imageKey,exit},people,beats:beats.map((b,i)=>({...b,id:`${lesson}-${String(n).padStart(2,'0')}-b${i+1}`,clueId:`${lesson}-${String(n).padStart(2,'0')}-b${i+1}-clue`,clueTitle:b.title})),finale:{intro:exit.problem,slots,conclusion}});
const q=(id,question,concepts,sourceBlocks,options)=>({id,question,concepts,sourceBlocks,options});
const rotate=(arr,by)=>arr.slice(by).concat(arr.slice(0,by));
